INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(13900, 0, 139, 0, 0, 0, 'Eastern Plaguelands', 'Before the plague these hills and forests were the Eastweald, the eastern heart of Lordaeron, governed from Stratholme, the second city of the kingdom. Here Prince Arthas put Stratholme to the sword rather than let its plagued people rise, and here the Scourge made its deepest home. Blight has swallowed the land. Rot runs through the woods, plaguehounds and plaguebats hunt the hills, and towns such as Darrowshire, Corin''s Crossing and Northdale belong to the dead. Baron Rivendare rules Stratholme for Kel''Thuzad. The living hold on where they can. The Argent Dawn keeps Light''s Hope Chapel, the Scarlet Crusade rules Tyr''s Hand, Mossflayer trolls cling to Zul''Mashar and high elf rangers guard a lodge near the road to Quel''Thalas. An old hermit keeps a hut by the Thondroril, and the Forsaken champion Nathanos Blightcaller hunts from the Marris Stead.', 'warcraft.wiki.gg/wiki/Eastern_Plaguelands (Eastweald, regional government in Stratholme, Culling, Naxxramas over the Plaguewood then moved to Dragonblight, Acherus over the eastern part of the zone in Wrath); quest 5263 description (Kel''Thuzad''s errand boy rules over Stratholme: Baron Rivendare); quest 5543 description (wildlife transformed into man eating beasts); quest 5961 description (Nathanos at the Marris Stead); zone_areas: Mossflayer trolls in 2273, high elf rangers in 2276, Scarlet Crusade in 2266, Argent Dawn in 2268'),
(13901, 1, 139, 1, 0, 0, 'The Thondroril River', 'The Thondroril runs south along the western edge of the Eastern Plaguelands, the border with the western lands. On its bank stands a small hut where an old hermit lives with his horse, Mirador. He asks little of visitors beyond help keeping the plaguehounds and plaguebats at bay, and he is laying in carrion worm meat for the winter, since the grubs are the only beasts in the region the plague has left untouched. He asks every guest to honor one credo: race does not dictate honor. Crypt fiends of the Scourge prowl the hills not far from his door.', 'AreaTable: 2619 Thondroril River, parent 139; posarea: Tirion Fordring 1855 and Mirador 11710 stand in area 2619; warcraft.wiki.gg/wiki/Tirion_Fordring (cottage on the shores of the Thondroril River, horse Mirador); quests 5542, 5543, 5544 descriptions (plaguehounds, plaguebats, carrion worms the only beasts unaffected, food for winter); npc_text 4254 (race does not dictate honor); zone_areas 2619: Crypt Horror, Crypt Stalker, Crypt Walker, Crypt Slayer; western_plaguelands.json 2810 (Thondroril runs along the border)'),
(13902, 1, 139, 2, 0, 0, 'The Marris Stead', 'The Marris Stead in the southwest was the family farm of Nathanos Marris, a ranger lord of Lordaeron. The Scourge swept over it in the war, and he has come home to it in undeath as Nathanos Blightcaller, champion of the Banshee Queen. He keeps his blighthounds here and receives the recruits she sends to train under him, few of whom he thinks worth the trouble; he claims to have sent every one of them back to her in pieces. Skulls and mangled human remains lie about the fields.', 'warcraft.wiki.gg/wiki/Marris_Stead (home of Nathanos Marris, killed there by Ramstein, returned on Sylvanas'' orders with his blighthounds); quest 6163 description (On this very stead I stood... I woke as Scourge); quest 5961 description (resides at the Marris Stead); npc_text 4814 (sent every one of you back to her in pieces); zone_areas 2260: Nathanos 11878, Blighthound 11885 x2, Human Skull 12202 x8, Mangled Human Remains 177804-177806'),
(13903, 1, 139, 3, 0, 0, 'The Undercroft', 'The Undercroft is an old crypt in the far southwest of the Eastern Plaguelands, its graves long left to the dead. It now shelters dead troll thieves, unliving Mossflayers and zombies under Zaeldarr the Outcast, who raid the corpse pit at Light''s Hope Chapel by night and carry the bodies back here to their hideout. A torn scroll by the crypt tells of a doomed troll named Hameya and a chest buried in the dirt behind it.', 'quest 5781 description (false grave at the Undercroft, hammer buried with my memory); quest 6021 description (dead troll thieves, Zaeldarr, steal bodies from the pit, hideout the Undercroft to the west); quest 6024 description (scroll: chest buried behind this crypt); zone_areas 2261: Zaeldarr 12250, Unliving Mossflayer, Mossflayer Zombie, Torn Scroll 177667, Mound of Dirt 177675; warcraft.wiki.gg/wiki/Undercroft (crypt in the southwest, Tirion''s substitute grave, Zaeldarr raids the grave pit)'),
(13904, 1, 139, 4, 0, 0, 'Darrowshire', 'Darrowshire, named for Darrowmere Lake to its west, was a village of humble, hardworking folk in the southern foothills, until the Scourge came. Its militia under Captain Joseph Redpath, a company of troops and paladins of the Silver Hand stood against the ghoul lord Horgus and the death knight Marduk the Black, and the village did not survive the night. Now it is silent ruin. In one house the ghost of a little girl, Pamela Redpath, still waits for her father to come home, and pieces of her lost doll lie scattered through the town.', 'page_text 2371-2376 (Annals of Darrowshire: named from Darrowmere Lake, southern foothills, humble yet hardworking, militia, troops, paladins, Horgus, Marduk, corruption, betrayal); quest 5149 description (stay in our house, doll left in town); zone_areas 2262: Pamela Redpath 10926, Pamela''s Doll''s Head/Left Side/Right Side 176116, 176142, 176143, Ghost of the Past 10940; warcraft.wiki.gg/wiki/Darrowshire (silent ruins, ghosts and memories)'),
(13905, 1, 139, 5, 0, 0, 'Corin''s Crossing', 'Corin''s Crossing grew up where the roads met between Andorhal, Darrowshire, Stratholme and Tyr''s Hand. The Scourge holds it now. Dark casters and summoners of the Cult of the Damned work among ghouls, shriekers and stitched horrors, and unseen servants walk its streets. Many of its ghouls were once the good folk of Darrowshire, still bound in their rotting bodies. Old battles cling to the place: near here a dwarf captain shattered the sword of Marduk the Black on his shield.', 'warcraft.wiki.gg/wiki/Corin%27s_Crossing (crossroads between Andorhal, Darrowshire, Stratholme and Tyr''s Hand; Scourge and Cult of the Damned); zone_areas 2264: Hate Shrieker, Vile Tutor, Dark Caster, Gibbering Ghoul, Dark Summoner, Stitched Horror, Unseen Servant, Scourge Warder; creature_template subnames: Dark Summoner, Vile Tutor <Cult of the Damned>; quest 5211 description (defenders roam as servants of the Scourge, in Plaguewood and Corin''s Crossing); page_text 2384 (sword shattered near Corin''s Crossing on a dwarf captain''s shield); page_text 2391 (Carlin found near Corin''s Crossing)'),
(13906, 1, 139, 6, 0, 0, 'The Infectis and Pestilent Scars', 'Two great wounds cut the land west and south of Corin''s Crossing. The Infectis Scar was made by dark magic. When the rune-laden sword of Marduk the Black broke against a dwarf''s shield, the blade sank into the earth and corrupted it, eating out the gorge that bears its sickness still; the shattered sword lies at its bottom, and spectral marauders and corpses stalk its floor. The Pestilent Scar is a natural rift, but the plague has found it all the same. Living decay and rotting sludges ooze along both gorges, and the bones of the land show through the rock.', 'page_text 2384 (Marduk''s rune-laden sword sank into the earth, gorge now known as the Infectis Scar); quest 5181 description (sword lies at the bottom of the gorge west of Corin''s Crossing); warcraft.wiki.gg/wiki/Infectis_Scar (caused by dark magic, unlike the natural Pestilent Scar); zone_areas 2623: Shattered Sword of Marduk 176209, Spectral Marauder, Spectral Corpse, Living Decay, Rotting Sludge; 2622: Living Decay, Rotting Sludge'),
(13907, 1, 139, 7, 0, 0, 'Blackwood Lake', 'Blackwood Lake lies northwest of Corin''s Crossing, its waters fouled and stalked by plague monstrosities. A town named Blackwood once stood here, burned by orcs in the Second War and remembered as the home of Grand Marshal Othmar Garithos. Its waters hold a darker relic. After the Battle of Darrowshire the Scourge carried off the skull of the fallen ghoul lord Horgus to spread dread, and when paladins of the Silver Hand destroyed the company that bore it, they cast the skull into the lake. Spectral betrayers and defenders still fight along its shores, as if that night has never ended.', 'quest 5181 description (lake northwest of Corin''s Crossing, his skull remains there); page_text 2383 (skull carried to sow dread, company defeated by Silver Hand paladins, cast into Blackwood Lake); warcraft.wiki.gg/wiki/Blackwood_Lake (town of Blackwood, home of Othmar Garithos); warcraft.wiki.gg/wiki/Eastern_Plaguelands (Second War: orcs burned Blackwood); zone_areas 2624: Horgus'' Skull 176208, Spectral Betrayer 11288, Spectral Defender 11289, Plague Monstrosity, Blighted Horror; warcraft.wiki.gg/wiki/Eastern_Plaguelands (orcs burned the small town of Blackwood in the Second War)'),
(13908, 1, 139, 8, 0, 0, 'Tyr''s Hand', 'In the southeast stands Tyr''s Hand, a walled city named for an ancient keeper and one of the oldest holy sites of the Church of the Light. The Scarlet Crusade rules it now as its stronghold in the east. Warders, praetorians, clerics and archmages fill its streets, inquisitors keep their own grim watch, and the Scarlet Basilica rises at its heart. Crusader Lord Valdelmar commands within, with High General Abbendis close at hand, and each day a courier rides in with reports from the Crusade''s command in Stratholme. A camp outside the walls marks how far the Crusade dares to reach.', 'warcraft.wiki.gg/wiki/Tyr%27s_Hand (named for Keeper Tyr, one of the oldest holy sites, Valdelmar held the city, Scarlet Basilica); zone_areas 2266: Scarlet Warder, Enchanter, Cleric, Praetorian, Curate, Archmage, Inquisitor, Valdelmar 11898, High General Abbendis 10828; 2265 Scarlet Base Camp: Scarlet Warder, Enchanter, Cleric; quest 6145 description (each day a report is sent from their central command to Tyr''s Hand); quest 6146 description (deliver to Crusader Lord Valdelmar in Tyr''s Hand)'),
(13909, 1, 139, 9, 0, 0, 'Light''s Hope Chapel', 'Light''s Hope Chapel was among the oldest and most revered holy sites of the Eastweald, and the remains of Lordaeron''s heroes lie in the catacombs beneath it. The Argent Dawn has made it the headquarters of its war on the Scourge, under Lord Maxwell Tyrosus. Horde and Alliance alike are welcome. The Dawn''s officers hand out its commission and pay for the scourgestones brought back from the field, a demolitions man takes contracts against Scourge buildings, and a caretaker tosses the corpses carried in from the field into a pit below.', 'warcraft.wiki.gg/wiki/Light%27s_Hope_Chapel (one of the oldest and most revered holy sites in the Eastweald, Sanctum of Light catacombs with heroes'' remains, Argent Dawn HQ); warcraft.wiki.gg/wiki/Eastern_Plaguelands (travel hub for both factions, led by Lord Maxwell Tyrosus); zone_areas 2268: Rayne 16135 <Cenarion Circle>, Rimblat Earthshatter 16134 <The Earthen Ring>, Scarlet Commander Marjhan 16114, Brotherhood of the Light NPCs, Caretaker Alen 11038; npc_text 8354 (Marjhan: emissary of the Scarlet Crusade), npc_text 3935 (Alen: I toss them in the pit); creature_text 29175 groups 28, 29 and 29173 group 85 (what lies beneath the chapel; the Light of Dawn); creature_text 29173 groups 26, 85 (We have lost. The Light... this place; the Light of Dawn is uncovered); quest 5503 reward text (commission, scourgestones); quest 6026 description (Smokey''s demolition work for the Argent Dawn)'),
(13910, 1, 139, 10, 0, 0, 'The Noxious Glade', 'North of Light''s Hope Chapel the ground sinks into the Noxious Glade, a sickly hollow held by the Scourge. Shadowmages and dark adepts of the cult keep company with stitched golems, dread weavers and hulking Scourge champions, some of them veterans of the slaughter at Darrowshire, while banshee death singers and unseen eyeless watchers drift among them. A cult deathspeaker named Selendre is sometimes seen in the glade.', 'zone_areas 2270: Shadowmage, Dark Adept, Stitched Golem, Dread Weaver, Scourge Champion, Deathspeaker Selendre 10827 <Cult of the Damned> (rare), Knight of the Ebon Blade, Risen Drudge; quest 5206 description (scourge champions who took part in the battle of Darrowshire, Noxious Glade to the north); warcraft.wiki.gg/wiki/Eastern_Plaguelands (from the Noxious Glade a cave leads to Death''s Breach); zone_areas 2270: Death Singer, Eyeless Watcher'),
(13911, 1, 139, 11, 0, 0, 'Northdale', 'Northdale was a hamlet in the northeast of the Eastweald until the war tore through it, and only the dead keep it now. Banshee death singers wail among the ruins, unseen eyeless watchers keep their vigil in the streets, and blighted horrors and monstrous plaguebats roam the ground around it. West of the town crawls Borelgore, a bloated maggot beast whose girth grows with everything it eats, and which has cost the Blightcaller whole regiments.', 'quest 5845 description (pushed to Northdale, final stand, threw down the standard); quest 5845 reward text (tattered state); zone_areas 2272: Symbol of Lost Honor 177264, Death Singer, Eyeless Watcher; warcraft.wiki.gg/wiki/Northdale (haunted by banshees and invisible eyeless watchers); quest 6136 description (Borelgore west of Northdale, lost entire regiments); zone_areas 2272: Blighted Horror, Monstrous Plaguebat'),
(13912, 1, 139, 12, 0, 0, 'Zul''Mashar', 'Zul''Mashar in the far northeast is the capital of the Mossflayers, a small tribe of forest trolls worn down by long wars with the humans of Lordaeron. The plague has found them too. Shadowhunters, scouts and cannibals crowd the ruins under Warlord Thresh''jin, and above them rises the ziggurat of Mazra''Alor. Scholars seek the Mosh''aru tablets held here, said to speak of Hakkar.', 'warcraft.wiki.gg/wiki/Zul%27Mashar (capital of the Mossflayer tribe, small forest troll tribe, long fighting with the humans of Lordaeron, Mazra''Alor ziggurat, Thresh''jin); quest 6024 description (Hameya: ate bad meat, the lich''s words urging me to reach Zul''Mashar and infect more); zone_areas 2273: Mossflayer Shadowhunter, Cannibal, Scout, Warlord Thresh''jin 10822, Infiltrator Hameya 12248, Third and Fourth Mosh''aru Tablets; quest 5065 description (tablets held by mossflayer trolls; first tablets spoke of the essence of Hakkar)'),
(13913, 1, 139, 13, 0, 0, 'Quel''Lithien Lodge', 'In the northern hills, near the road that leads on to Quel''Thalas, stands Quel''Lithien Lodge, a hunting lodge of the high elves that once hosted Farstrider rangers. Rangers, pathstriders and woodsmen keep it still under Ranger Lord Hawkspear, friendly to the Alliance and quick to draw on the Horde. Nearby lives the priestess Aurora Skycaller, who grieves that her people are as shattered as any broken relic, yet will mend an old highborne crystal for those who ask sincerely.', 'warcraft.wiki.gg/wiki/Quel%27Lithien_Lodge (high elven hunting lodge near the entrance to Quel''Thalas, Farstrider camp, friendly to Alliance until Cataclysm); zone_areas 2276: Ranger, Woodsman, Pathstrider, Ranger Lord Hawkspear 10824, Quel''Thalas Registry 177747, Aurora Skycaller 10304; FactionTemplate 1576: hostile to Horde, not to Alliance; quest 6133 description (registry, a document detailing my life); npc_text 5817 (my people are as shattered as the relic); quests 5246, 5247, 5248 (Crystal of Zin-Malor)'),
(13914, 1, 139, 14, 0, 0, 'The Watchtowers', 'Four old towers of Lordaeron stand over the Eastern Plaguelands: Crown Guard Tower in the south, Eastwall Tower in the east, the Northpass Tower near the road to the north, and Plaguewood Tower at the edge of the blighted forest. All were left empty when the kingdom fell, abandoned since the days of Lordaeron, and plaguebats, plaguehounds and carrion devourers now prowl around their walls. Banners still hang from their poles, waiting for someone to claim them.', 'quest 9664 description (towers long abandoned since the days of Lordaeron, seized and rebuilt, tighten the noose); quest 9665 description (Forsaken agents uncovered the Alliance plot; drive them out); zone_areas: Tower Banner 182106 and capture doodads in 2263, 2271, 2275, 4067; Emissary Whitebeard 17069 and Gormok 17072 in 2268; warcraft.wiki.gg/wiki/Crown_Guard_Tower (destroyed in the Scourge invasion, contested by Alliance and Horde); zone_areas 2263, 2271, 2275, 4067: Plaguebat, Plaguehound, Carrion Devourer, Tower Banner 182106'),
(13915, 1, 139, 15, 0, 0, 'Plaguewood', 'The Plaguewood spreads south of Stratholme, the most diseased corner of a diseased land. It was once a fair woodland that Prince Arthas crossed on his road to the city; since the Culling the blight has swollen it with giant mushrooms and rot. The Scourge has raised ziggurats and slaughterhouses among the trees, guarded by stitched horrors, cannibal ghouls and cursed mages, and the Argent Dawn pays demolition crews to bring them down.', 'warcraft.wiki.gg/wiki/Plaguewood (south of Stratholme, most infested part, once beautiful woodland, Arthas crossed it, giant mushrooms, ziggurats and slaughterhouses, Naxxramas floated above and left for Dragonblight, Argent Dawn controlled access); quests 6026, 6041 (Smokey''s Argent Dawn demolition of ziggurats and slaughterhouses); zone_areas 2277: Stitched Horror, Cannibal Ghoul, Cursed Mage, Scourge Structure, Ziggurat/Slaughterhouse Protector'),
(13916, 1, 139, 16, 0, 0, 'Terrordale', 'Terrordale was a small town at the western edge of the Plaguewood, now a ghost town of plagued swine and Scourge soldiers. It still has a merchant. Augustus the Touched was lodging at the inn when the Scourge came, and he has been here ever since, eager to buy and sell anything at prices he calls insane, if only someone would fetch the receipt book he left in his room. Sharing his house is Egan, a dwarf who hates the Scourge but pities its victims, and who has built a blaster to free the restless souls of Stratholme.', 'warcraft.wiki.gg/wiki/Terrordale (small town at the edge of Plaguewood, ruined ghost town); zone_areas 2627: Plagued Swine, Scourge Soldier, Augustus the Touched 12384, Egan 11140, Augustus'' Receipt Book; npc_text 4979, 4980; creature_text 12384; quest 6164 description (room in the inn); warcraft.wiki.gg/wiki/Augustus_the_Touched (staying at the inn when the Scourge came); warcraft.wiki.gg/wiki/Egan (dwarf living in Augustus'' house); quests 5281, 5282 (Egan, compassion, blaster)'),
(13917, 1, 139, 17, 0, 0, 'Stratholme', 'Stratholme was the second city of Lordaeron and the seat of the Eastweald. When the plague reached it in tainted grain, Prince Arthas ordered its people put to death before they could rise, and the city burned. Many chose the flames over becoming Scourge, and their restless spirits still walk its streets. Today Baron Rivendare holds most of the city for Kel''Thuzad, while the Scarlet Crusade has walled itself into the Scarlet Bastion under its Grand Crusader. On its eastern side, at Eastwall Gate, a service entrance leads into the Elders'' Square.', 'warcraft.wiki.gg/wiki/Stratholme (second largest city, tainted grain from Andorhal, the Culling, Rivendare under Kel''Thuzad, Scarlet Bastion under the Grand Crusader); quest 5281 description (many hurled themselves into the flames rather than become Scourge; restless spirits); quest 5263 description (Rivendare, Kel''Thuzad''s errand boy); quest 6144 reward text (Grand Crusader sits safely in the Scarlet Bastion); zone_areas 2625: Elders'' Square Service Entrance 175369'),
(13918, 2, 139, 1, 0, 0, 'Tirion Fordring', 'For years Tirion Fordring has lived as a hermit in a small hut by the Thondroril, with his old horse Mirador for company. He holds to one credo and asks every guest to respect it: race does not dictate honor. He has known orcs as honorable as the noblest knights and humans as vile as the most ruthless Scourge, though he will not bore a visitor with tales of his youth. The Plaguelands are hard on an old man, and he gladly accepts help keeping the beasts at bay and filling his larder for the winter.', 'warcraft.wiki.gg/wiki/Tirion_Fordring (Silver Hand, Lord of Mardenholde, Eitrigg, trial and exile, hermit by the Thondroril with Mirador, Argent Crusade); npc_text 4494 (banished, chose to remain to watch over Taelan; Taelan their Highlord); quest 5781 description (his mother told him I had died); npc_text 4254 (race does not dictate honor; orcs as honorable as knights); creature_text 12126 groups 6, 7 (malaise; a new Order is born); creature_text 29175 (Tirion at Light''s Hope Chapel)'),
(13919, 2, 139, 2, 0, 0, 'Nathanos Blightcaller', 'In life Nathanos Marris was a ranger lord of Lordaeron, trained by the high elves to a rank no other human had held. Now, as Nathanos Blightcaller, he is among the first and most dedicated champions of the Banshee Queen. He keeps the Marris Stead with his blighthounds, roaming the wastes to slay all Scourge and Alliance that cross his path, and trains the recruits the Dark Lady sends him with open contempt, calling every one of them imbecile. He guards the secrets of his mortal life jealously. To the Alliance he is a hero lost.', 'quest 6186 description (the only human ever allowed to train under the high elves); quest 6163 description (stood on this stead, woke as Scourge, she came for me); quest 5961 description (among the first of my champions; slaying all Scourge and Alliance); npc_text 4814; quests 6022, 6133, 6135 (imbecile; do not read the registry); quest 6187 description (Order Must Be Restored: destroy the Blightcaller); FactionTemplate 1174: hostile to Alliance'),
(13920, 2, 139, 3, 0, 0, 'Lord Maxwell Tyrosus', 'Lord Maxwell Tyrosus leads the Argent Dawn from Light''s Hope Chapel. A veteran of the Third War who fought beside Uther the Lightbringer, he left the Silver Hand when it hardened into the Scarlet Crusade and rose to command the Dawn. He keeps to the church and grants audience to outsiders only rarely; years can pass between such honors, and the Argent Hold, the Dawn''s sealed vault, stays locked until a champion has truly earned it.', 'warcraft.wiki.gg/wiki/Maxwell_Tyrosus (fought with Uther at Andorhal, left when the Silver Hand became the Scarlet Crusade, leader of the Argent Dawn, Second Battle); quest 5264 description (years since Maxwell has granted audience to outsiders; inside the church); quest 5265 description (the Argent Hold has remained locked through the years); creature_text 29178 group 7 (Stand fast, brothers and sisters! The Light will prevail!)'),
(13921, 2, 139, 4, 0, 0, 'Duke Nicholas Zverenhoff', 'Duke Nicholas Zverenhoff is one of the Argent Dawn''s most respected leaders. He issues the Dawn''s commission to all who fight under its banner and pays for the scourgestones they bring back as proof. He holds that anything taken to an extreme endangers the world, the Scarlet Crusade''s blind zealotry above all, and he counsels his champions to be tolerant yet rigid in their beliefs. He takes a keen interest in the Crusade''s archivist in Stratholme and the records he guards.', 'warcraft.wiki.gg/wiki/Nicholas_Zverenhoff (one of the Dawn''s most respected leaders); quest 5503 reward text (all who fight on behalf of the Argent Dawn must don our commission; scourgestones); quest 5251 description and request text (anything taken to an extreme; tolerant yet rigid); quest 5262 description and reward text (Grand Crusader a demon, brother to Varimathras; pawns of a greater evil)'),
(13922, 2, 139, 5, 0, 0, 'Leonid Barthalomew the Revered', 'Leonid Barthalomew died in the Scourging of Lordaeron and served the Lich King as a mindless thrall, until the Banshee Queen set him free. He chose the Argent Dawn over the Forsaken. He treats his undeath as a malady to be endured and a weapon to be turned on the Scourge, and cares nothing for the reverence his colleagues show him. He has played tricks of his own on the Scourge, and there are memories of Stratholme he would rather not stir.', 'quest 5462 description (undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the Argent Dawn); quest 5243 description (undeath a malady; accolades mean nothing); quest 5463 description (watched Ras Frostwhisper become a lich); quest 5462 request text (questions you do not want answers); warcraft.wiki.gg/wiki/Leonid_Barthalomew_the_Revered (killed in the Scourging, led the defense until Tirion arrived); burning_steppes.json 4624 (his trick on Vectus, mentioned only in passing); warcraft.wiki.gg/wiki/Leonid_Barthalomew_the_Revered (led the Argent Dawn against the death knights before Tirion arrived)'),
(13923, 2, 139, 6, 0, 0, 'Carlin Redpath', 'Carlin Redpath serves the Argent Dawn at Light''s Hope Chapel, and the fall of Darrowshire haunts him. Many of the village''s defenders died in that battle, and many roam again as ghouls of the Scourge; he dreams of them crying out to him and asks that their souls be set free. He will not let the tragedy drag him into despair. He holds his memories close, waiting for a reckoning.', 'quest 5211 description and request text (defenders roam as Scourge; cry out to me in my dreams); npc_text 4716 (tragedies; hold those memories close; a reckoning); posarea: Carlin 11063 in area 2268; page_text 2391; quest 5241 description'),
(13924, 2, 139, 7, 0, 0, 'Pamela Redpath', 'Pamela Redpath was a little girl when the Scourge came to Darrowshire. Her aunt Marlene hid her in the family home and told her to stay put while her father went to fight, and she has stayed ever since. Her ghost does not understand what happened. She waits for her daddy, the bravest man in the whole world, asks after her aunt and uncle, and wants her doll, which she left somewhere in town. Sometimes bad people come and whisper to her.', 'quest 5149 description (auntie told me to stay; father had to fight; bad people whisper; doll); quest 5601 description and reward text (Jessica fled; Pamela on Jessica crying); quests 5152, 5241 (aunt and uncle); quest 5142 description (Marlene hid her niece); DB: Jessica Redpath 11629 spawned on map 1 at Everlook, Winterspring; warcraft.wiki.gg/wiki/Pamela_Redpath (youngest daughter of Joseph, killed in the battle)'),
(13925, 2, 139, 8, 0, 0, 'Joseph Redpath', 'Captain Joseph Redpath led Darrowshire''s militia when the Scourge attacked, and he fought bravely until the death knight Marduk the Black rode up to him in the thick of battle and tore his spirit loose with black magic. Twisted into an evil shadow of himself, he spread his taint among the defenders, who turned on their allies and slaughtered the town. His cracked shield was cast aside, his corrupted spirit went on to ravage Lordaeron, and his daughter Pamela was left waiting for him. Only by changing the course of that battle can his soul be won back.', 'page_text 2372, 2375, 2376 (Annals: militia, Marduk tore loose his spirit, defenders betrayed and slaughtered the town, tore into Lordaeron); quest 5168 description (shield cracked and discarded); quest 5721 description (Redpath must survive to be corrupted, then defeated; his spirit saved); creature 10936 Joseph Redpath (gossip, spirit after the battle), 10938 Redpath the Corrupted (hostile)'),
(13926, 3, 139, 1, 0, 0, 'The Fordring Redemption', 'The hermit by the Thondroril asks small things first. He would have the plaguehounds and their runts thinned, the plaguebats cleared from the skies and several hundred pounds of carrion worm meat laid in for the winter, since the grubs are the only beasts the plague has spared. He warns of the Scarlet Crusade, which kills any who do not bear its mark, and of wild beasts the blight has made into man eaters. He offers little in return but a warm meal and talk of days long past, yet he watches each helper closely, for few would selflessly aid an old and forgotten hermit.', 'quests 5542, 5543, 5544 descriptions and reward texts; quest 5742 and gossip menus 3681-3683 (npc_text 4493-4495); quests 5781, 5845, 5846, 5848 descriptions and reward texts; quest 5861 description; quest 5848 description (search for a painting of our twin moons, chip away at the paint)'),
(13927, 3, 139, 2, 0, 0, 'In Dreams', 'Disguised by Myranda''s illusion as a Scarlet soldier, a stranger reached Mardenholde Keep in Hearthglen and laid Tirion''s gifts before Highlord Taelan Fordring. The truth undid him. He fell to one knee, and for a moment it seemed the fury of ages would be loosed upon the town. For years, he confessed, he had been the Grand Crusader''s puppet, kept alive only by memories of his father and by dreams of fighting at his side. He wanted to dream no more. He asked to be taken to Tirion, and led the way out through Hearthglen toward the forest''s edge.', 'quest 5862 log and reward text (Scarlet Illusion, Mardenholde Keep); quest 5944 description and reward text; creature_text 1842, 1840 (Isillien: forest''s edge, Grand Crusader charged me), 12126 (murdered my boy; too long have I sat idle; a new Order is born); warcraft.wiki.gg/wiki/Tirion_Fordring (Isillien killed Taelan in Hearthglen; Tirion avenged his son); creature_text 1840 group 0 (you will not make it to the forest''s edge)'),
(13928, 3, 139, 3, 0, 0, 'Little Pamela', 'Two women ask after the same child. In Winterspring, Jessica Redpath, who fled Lordaeron during the great war and escaped before the Scourge swept through it, fears her whole family was killed at the battle of Darrowshire and begs for news of her little sister, Pamela. On a hill south of Andorhal, the spirit of Marlene Redpath remembers how many died at that battle, and worse; when it began she hid her niece Pamela, and she has never learned what became of the girl. Both point to Darrowshire, in the southern hills beyond Gahrron''s Withering.', 'quests 5142, 5601, 5149, 5152, 5241 descriptions and reward texts; creature_text 10926 group 4 (Hurray! My doll!)'),
(13929, 3, 139, 4, 0, 0, 'The Annals of Darrowshire', 'Two threads of Darrowshire''s story lead here. In the ruined inn of Andorhal, the bronze dragon Chromie believes the fate of Joseph Redpath, a doomed hero of that battle, can still be changed, but first it must be learned, and she sends for the Annals of Darrowshire, a book held in Andorhal''s city hall. At Light''s Hope Chapel a man of the Argent Dawn dreams of Darrowshire''s fallen defenders crying out to him. Many of them roam again as the Scourge''s ghouls in Plaguewood and Corin''s Crossing, and he asks that they be found and their souls set free.', 'quests 5154, 5210 descriptions and reward texts; quests 5168, 5181 descriptions; quest 5211 description; page_text 2371-2391 (Annals and Extended Annals)'),
(13930, 3, 139, 5, 0, 0, 'The Battle of Darrowshire', 'With the relics of Darrowshire gathered, Davil Lightfire''s libram, Joseph Redpath''s cracked shield, the skull of Horgus and the shattered sword of Marduk, Chromie says they are reagents for a great spell, and one more is needed: skulls of the Scourge champions who fought at Darrowshire. Carlin Redpath hands over an enchanted crystal that resonates when passed over such a skull, and sends hunters to the Noxious Glade to the north and the Fungal Vale to the west. Chromie has told him that the spell will give them a chance to save Darrowshire.', 'quests 5206, 5941, 5721, 5942 descriptions and reward texts; creature_text 10936 (Pamela? ... I''m finally home), 10944, 10937, 10938, 10948 (battle lines)'),
(13931, 3, 139, 6, 2, 0, 'The Blightcaller''s Imbeciles', 'Sylvanas sends her promising soldiers east to Nathanos Blightcaller, one of the first of her champions, and he greets each as fodder for his hounds. Training at the Marris Stead is whatever he needs done. Recruits fetch living rot from the Scourge of Corin''s Crossing and grind it down to feed the blighthounds, clear the plaguebats from his fields, raid Quel''Lithien Lodge for a registry of his mortal life that they are forbidden to read, and hunt Duskwing, an albino demon bat, and Borelgore, a maggot beast that has cost him whole regiments. He calls every one of them imbecile.', 'quests 5961, 6022, 6042, 6133, 6135, 6136, 6163 descriptions, request and reward texts'),
(13932, 3, 139, 7, 2, 0, 'The Scarlet Oracle', 'The Undercity has resolved to strike back at the Scarlet Crusade. Sylvanas herself has asked Nathanos Blightcaller to send his most capable agents for a sensitive operation, though by his account his best were killed years ago and he must make do with what he has. The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into Forsaken lands, desecrating their monuments and murdering their people. His command is too well defended to strike directly, but Forsaken deathstalkers have found a weakness: each day a report travels from the Crusade''s central command to Tyr''s Hand in the hands of the Crimson Courier.', 'quests 6144, 14349 descriptions and reward texts; quests 6145, 14350 descriptions; quests 6146, 6147, 6148 descriptions and reward texts; disables table: quests 6144 and 6145 disabled'),
(13933, 3, 139, 8, 0, 13, 'The Light of Dawn', 'To the defenders of Light''s Hope Chapel, it began as the end of the world. Highlord Darion Mograine marched the Lich King''s army and the death knights of Acherus against the chapel, and Korfax, Lord Maxwell Tyrosus, Leonid Barthalomew, Duke Zverenhoff and the Dawn''s defenders held as long as they could. Darion''s own blade, the corrupted Ashbringer, had begun to defy him, and more than a hundred defenders had fallen when Tirion Fordring arrived. Tirion told Darion that his master knew what lay beneath the chapel and had sent him there to die.', 'zone_the_scarlet_enclave.cpp (npc_highlord_darion_mograine Light of Dawn event: defenders Korfax 29176, Eligor 29177, Tyrosus 29178, Leonid 29179, Zverenhoff 29180, Rayne 29181, Rimblat 29182); creature_text 29173 groups 68-85 (army marches, over a hundred Defenders fall before Tirion arrives, Ashbringer thrown and cleansed, Alexandros arrives); creature_text 29175 groups 28-29, 53-66 (what lies beneath the chapel; union; The Argent Crusade comes for you); creature_text 29183 groups 47-58 (Lich King: draw Tirion out; not on holy ground); warcraft.wiki.gg/wiki/Light%27s_Hope_Chapel (Second Battle)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(13900, 1, 0, 12, 'Above the Plaguewood, south of Stratholme, hangs the necropolis Naxxramas, the floating citadel of Kel''Thuzad and the seat of his power in the Plaguelands. Its dark shape looms over the blighted forest, and the Scourge that hold the Eastweald answer to the lich within.', 'warcraft.wiki.gg/wiki/Naxxramas (Kel''Thuzad''s citadel above the Plaguewood until it moved to Dragonblight); mod-individual-progression naxx40_gameobjects.sql (necropolis 181056 spawned over the Plaguewood as a transport with no visibility script); quest 5263 description (Kel''Thuzad''s errand boy rules over Stratholme)'),
(13900, 2, 13, 255, 'In the war against the Lich King the Scourge has turned its greatest strength north to Northrend, and the eastern Plaguelands are no longer the heart of its power. Above the eastern hills near Light''s Hope Chapel now floats Acherus, the Ebon Hold, the death knights'' fortress.', 'warcraft.wiki.gg/wiki/Eastern_Plaguelands (the Scourge war moves to Northrend in Wrath; Acherus over the eastern part of the zone); AreaTable 4281 Acherus: The Ebon Hold, parent 139'),
(13901, 1, 0, 255, 'The hermit has not been entirely truthful about who he is. Once he is certain a guest can be trusted, he gives his true story: he is Tirion Fordring, once Lord of Mardenholde, found guilty of treason and banished, who stayed in these lands to watch over his son, Taelan, now Highlord of the Scarlet Crusade.', 'npc_text 4493, 4494 (gossip of quest 5742: not entirely truthful about my identity; banished; chose to remain to watch over Taelan; their Highlord)'),
(13902, 1, 0, 255, 'This farm is where his first life ended. On this very stead he stood his ground in defense of Lordaeron until a great wave of Scourge overwhelmed him, and he woke as one of them, his mind bound to the Lich King''s, until the Banshee Queen came for him and set him free. The thing that cut him down he hunted for months, until it fled into Stratholme.', 'quest 6163 description and request text (On this very stead I stood... I woke as Scourge; she came for me; it fled to Stratholme)'),
(13903, 1, 0, 255, 'One of the crypt''s graves is a lie. When Tirion Fordring was banished for treason, his wife told their young son that he had died, and the boy was brought here to mourn at a false grave. There he buried his most cherished possession, a toy war hammer made in the image of his father''s, and with it his father''s memory.', 'quest 5781 description (his mother told him I had died; false grave at the Undercroft; miniature war hammer, an exact replica of my own; buried with my memory)'),
(13904, 1, 0, 255, 'The Annals of Darrowshire tell how the battle was lost. It was nearly won when Captain Joseph Redpath was corrupted by Marduk the Black, and his taint turned the defenders on their own allies, so that the town was slaughtered by those sworn to save it.', 'quest 5154 reward text (Redpath corrupted during the battle, betrayed the defenders); page_text 2371-2376 (Annals of Darrowshire)'),
(13905, 1, 0, 255, 'The new pages of the Annals of Darrowshire add a survivor''s tale. Days after the village fell, agents of the Argent Dawn found a wounded defender, Carlin Redpath, wandering near Corin''s Crossing, weak with thirst and fever, and carried him away to Light''s Hope Chapel.', 'page_text 2391 (The Fate of Carlin Redpath, in the pages Chromie''s magic adds); quest 5210 description (extra passages tell of Carlin, who survived)'),
(13909, 1, 6, 255, 'As the Scourge stirs against the wider world, the chapel has drawn new allies. Envoys of the Cenarion Circle, the Earthen Ring and even the Scarlet Crusade sit beside the Dawn''s own Brotherhood of the Light. The Scarlet emissary doubts they could even dent the armies of Kel''Thuzad, united or not, but hopes to hold them long enough for a miracle.', 'npc_text 8354 (Marjhan: emissary of the Scarlet Crusade; armies of Kel''Thuzad; contain them long enough for some sort of miracle); npc_text 8353 (Brotherhood of the Light); mod-individual-progression ipp_aware_npcs.sql (16112-16135, 17069, 17072 scripted npc_ipp_naxx40: shown from state 6)'),
(13909, 2, 13, 255, 'The chapel''s holy ground has since been tested. When the death knights of Acherus marched on it at the head of an army of the dead, its defenders held, and the Light beneath the chapel helped turn the attackers back.', 'creature_text 29175 groups 28, 29 and 29173 group 85 (what lies beneath the chapel; the Light of Dawn); creature_text 29173 groups 26, 68, 69 (army marches; We have lost. The Light... this place)'),
(13910, 1, 13, 255, 'The glade has new tenants. Knights of the Ebon Blade and their risen drudges now walk among the cultists, and from the glade a passage leads through to Death''s Breach, where the death knights gather beneath their floating fortress.', 'zone_areas 2270: Knight of the Ebon Blade 29202, Risen Drudge 29212, Lord Thorval 29196; zone_areas 4544 Death''s Breach: Knights of the Ebon Blade; warcraft.wiki.gg/wiki/Eastern_Plaguelands (from the Noxious Glade a cave leads to Death''s Breach)'),
(13911, 1, 0, 255, 'Northdale saw the end of a young paladin''s faith. When the Order of the Silver Hand was shattered after Uther''s death, Taelan Fordring held out as long as he could and was pushed back to this hamlet for a final stand, wondering whether any of the order still lived and whether it mattered. Here he threw down its standard and renounced all he had known, and the tattered banner still lies where it fell.', 'quest 5845 description (pushed to Northdale, final stand, threw down the standard); quest 5845 reward text (tattered state)'),
(13912, 1, 0, 255, 'A torn scroll tells how some of them were taken. A band of Mossflayers traveling to Zul''Mashar ate tainted meat on the road, and they changed. One of them, Hameya, began to hear a lich urging him to reach the city and infect more of his people, and before his will was gone he wrote a plea to be killed.', 'quest 6024 description (Hameya: ate bad meat while traveling to Zul''Mashar; the lich''s words urging me to infect more; kill me before it''s too late)'),
(13913, 1, 0, 255, 'Among the lodge''s papers lies the Quel''Thalas Registry, a document detailing the mortal life of Nathanos Blightcaller. He wants it back badly enough to send killers for it, with orders to leave strife and grief in their wake, and he forbids them to read a word of it.', 'quest 6133 description and reward text (registry, a document detailing my life as a mortal; leave strife and grief; do not read it)'),
(13914, 1, 6, 255, 'The towers will not stay empty. The Alliance means to seize and rebuild them, tightening a noose around the Forsaken lands to the west, while Forsaken agents have uncovered the plan and the Horde fights to drive them out. Envoys of both sides wait at Light''s Hope Chapel for news of who holds the towers.', 'quest 9664 description (towers long abandoned, seized and rebuilt, tighten the noose); quest 9665 description (Forsaken agents uncovered the Alliance plot; drive them out); mod-individual-progression ipp_aware_npcs.sql (Emissary Whitebeard 17069 and Gormok 17072 scripted npc_ipp_naxx40: shown from state 6)'),
(13915, 1, 0, 12, 'Above the forest hangs the necropolis Naxxramas, the floating citadel of Kel''Thuzad and the seat of his power in the Plaguelands, and the ziggurats and slaughterhouses among the trees stand in its shadow.', 'warcraft.wiki.gg/wiki/Plaguewood (Naxxramas floated above); mod-individual-progression naxx40_gameobjects.sql (transport 181056, Naxxramas floating in Plaguewood)'),
(13915, 2, 6, 12, 'Since the Scourge began to strike at the wider world, the Argent Dawn has controlled the way into the necropolis, and only those it judges worthy are let inside. The Dawn''s Brotherhood of the Light watches the citadel from Light''s Hope Chapel.', 'warcraft.wiki.gg/wiki/Plaguewood (the Argent Dawn controlled access); mod-individual-progression naxxramas_40.h (attunement quests 9121-9123) and ipp_aware_npcs.sql (Archmage Angela Dosantos 16116, Brotherhood of the Light, shown from state 6)'),
(13915, 3, 13, 255, 'The fighting has moved on. In the war against the Lich King the Scourge has turned its greatest strength north to Northrend, and the Plaguewood is no longer the heart of its power, though the ziggurats and slaughterhouses still stand among the rotting trees.', 'warcraft.wiki.gg/wiki/Plaguewood (the Scourge war moves to Northrend in Wrath); zone_areas 2277: Scourge Structure, Ziggurat/Slaughterhouse Protector'),
(13918, 1, 0, 255, 'Once certain a stranger could be trusted, Tirion told the truth about himself. He was a paladin of the Silver Hand and Lord of Mardenholde, master of Hearthglen, until he was found guilty of treason and banished; the old tale is that he stood by an honorable orc against his own people. He chose to stay close to watch over his young son, Taelan, who took his place as lord of Mardenholde and, in a cruel twist, rose to become Highlord of the Scarlet Crusade.', 'npc_text 4493, 4494 (gossip of quest 5742); warcraft.wiki.gg/wiki/Tirion_Fordring (Silver Hand, Lord of Mardenholde, Eitrigg, trial and exile)'),
(13918, 2, 0, 255, 'His exile cost him more than his rank. After his banishment his wife told the boy that his father had died, and Taelan was taken to mourn at a false grave in the Undercroft, where he buried a cherished toy hammer, a replica of Tirion''s own.', 'quest 5781 description'),
(13918, 3, 0, 255, 'His son''s death ended his long malaise. Taelan was murdered on the road from Hearthglen by Grand Inquisitor Isillien, and Tirion, who had sat idle so long, fought the Inquisitor and knelt over his boy. There he vowed that a new Order of the Silver Hand was born that day, sworn to stamp out the evil that plagues this world, and took his place as its Highlord.', 'quest 5944 reward text (I now take my place as Highlord of the new Order); creature_text 12126 groups 0, 6, 7'),
(13918, 4, 13, 255, 'In the war against the Lich King the hermit''s idleness is long over. Tirion Fordring has taken up the Ashbringer. At Light''s Hope Chapel he called for a union of the Argent Dawn and the Silver Hand, and now he leads the Argent Crusade against the Lich King in Northrend.', 'creature_text 29175 groups 63-66 (I call for a union; the Argent Dawn and the Order of the Silver Hand); warcraft.wiki.gg/wiki/Tirion_Fordring (Argent Crusade, Ashbringer, Northrend)'),
(13919, 1, 0, 255, 'His mortal life ended on his own farm. He stood his ground on the stead in defense of Lordaeron until a great wave of Scourge overwhelmed him, and he woke as one of them, his mind bound to the Lich King''s, until Sylvanas Windrunner came for him and set him free. He hunted the creature that killed him across the wastes for months, until it fled into Stratholme.', 'quest 6163 description and request text'),
(13920, 1, 13, 255, 'When the death knights of Acherus marched on the chapel with an army of the dead behind them, Tyrosus stood with its defenders and rallied them to hold fast, crying that the Light would prevail.', 'creature_text 29178 group 7 (Stand fast, brothers and sisters! The Light will prevail!)'),
(13921, 1, 0, 255, 'It was to Zverenhoff that proof came of the Crusade''s darkest secret: the Grand Crusader in Stratholme was a dreadlord, brother to Varimathras of the Undercity. The duke was left to wonder whether the Crusade had long served a demon unaware, the pawns of a greater evil.', 'quest 5262 description and reward text'),
(13922, 1, 0, 255, 'Pressed about Stratholme, he admits what he saw there. He watched the mage Ras Frostwhisper pledge his soul to the Lich King, draw a dagger across his own throat with a smile and rise as a lich within a pentagram, on ground the Lich King had blessed: Menethil''s Gift, holy ground to the Scourge.', 'quest 5463 description; quest 5462 request and reward text (memories I had hoped would never resurface)'),
(13922, 2, 13, 255, 'When the death knights of Acherus and an army of the dead marched on Light''s Hope Chapel, Leonid was among the defenders who stood against them, and he led the chapel''s defense until Tirion Fordring arrived.', 'warcraft.wiki.gg/wiki/Leonid_Barthalomew_the_Revered (led the defense until Tirion arrived)'),
(13923, 1, 0, 255, 'The Extended Annals of Darrowshire tell his story. Brother to Captain Joseph Redpath, he fell terribly wounded in the battle, and days later agents of the Argent Dawn found him wandering near Corin''s Crossing, weak with thirst and fever. They carried him to Light''s Hope Chapel, and in gratitude he joined their ranks to fight a war of revenge.', 'page_text 2391 (The Fate of Carlin Redpath, in the Extended Annals, item 13202, given with quest 5210); quest 5210 description'),
(13923, 2, 0, 255, 'He is uncle to little Pamela too. At night, far away in Darrowshire, his ghostly niece can hear him weeping, and she longs to hear again the story he used to tell her, about the rabbits and the berry jam.', 'quest 5241 description (I can hear my Uncle Carlin crying; the rabbits and the berry jam)'),
(13924, 1, 0, 255, 'She remembers a big sister too. Jessica went away long ago, crying so hard that Pamela could not understand why, and the two of them used to play and pick flowers around the house. Jessica lives still, far away in Winterspring, and it was she who sent a stranger to look for Pamela.', 'quest 5601 description and reward text; DB: Jessica Redpath 11629 spawned on map 1 at Everlook, Winterspring'),
(13924, 2, 0, 255, 'Her long wait is over. When the battle of Darrowshire was fought again and her father''s spirit saved, Pamela heard him whisper that he had chased the ghosts away and was coming home, and in her joy she made tea for her new friend, with lots of sugar.', 'quest 5721 reward text'),
(13925, 1, 0, 255, 'In the battle fought again, Redpath was corrupted as before and this time struck down, and so his spirit was saved. It rose in the town square calling for Pamela, and went home to her at last.', 'quest 5721 description (after defeating the corrupted Redpath, his spirit will be saved); creature_text 10936 groups 0, 1 (Pamela? Are you there, honey? ... I''m finally home)'),
(13925, 2, 0, 255, 'Speaking with the one who saved him, Joseph said that a darkness had fallen over his eyes until he was torn from his unholy reverie, and he begged that stranger to forgive him.', 'npc_text 4778 (gossip menu 30223 of Joseph Redpath 10936)'),
(13926, 1, 0, 255, 'Satisfied, the hermit told the truth. He is Tirion Fordring, once Lord of Mardenholde, found guilty of treason and banished, and his son Taelan, now Highlord of the Scarlet Crusade, is a good man who has forgotten what it is to be noble and honorable. Tirion believes that in his heart the boy knows what he does is wrong, and he asks for help to make him remember.', 'quest 5742 and gossip menus 3681-3683 (npc_text 4493-4495)'),
(13926, 2, 0, 255, 'Memories were to be gathered from Taelan''s past. From the Undercroft came the toy war hammer he had buried at his father''s false grave after his mother told him Tirion had died. From Northdale came the Silver Hand standard he threw down there in despair, as glorious to Tirion in its tattered state as the day he first swore his oath.', 'quests 5781, 5845 descriptions and reward texts'),
(13926, 3, 0, 255, 'Last came the painting. On Caer Darrow the ghost of the artist Renfray remembered the portrait he had painted of the Fordrings on the beach, and how after the trial he hid it where no one would look. Beneath the paint of a picture of the twin moons, deep in what is now the Scarlet Bastion of Stratholme, lay his masterwork, Of Love and Family. At the sight of it Tirion nearly collapsed, sobbing.', 'quest 5846 description and reward text; quest 5848 description and reward text'),
(13926, 4, 0, 255, 'One step remained. The gifts had to reach Taelan, whose crusaders would attack any messenger of Tirion''s on sight, so only a guise of deception would serve. Tirion sent the gifts south to Myranda, an old and trusted confidant who lives near Uther''s tomb, to find a way into Hearthglen.', 'quest 5861 description'),
(13927, 1, 0, 255, 'Grand Inquisitor Isillien met them on the road with his Crimson Elite, charged by the Grand Crusader to destroy Taelan and his new friends, and Taelan fell. Then Tirion himself arrived. The old man who had sat idle for so long fought the Inquisitor down and knelt over his son''s body, and there he made a vow: a new Order of the Silver Hand was born that day, sworn to stamp out the evil that plagues this world, and he would be its Highlord.', 'quest 5944 reward text; creature_text 1840 groups 0, 3 (forest''s edge; the Grand Crusader has charged me); creature_text 12126 groups 0, 6, 7'),
(13928, 1, 0, 255, 'In Darrowshire the child is found, still waiting in her family''s house. Pamela is a ghost, and she does not understand what happened. Her father, she says, is the bravest man in the whole world and will come for her. She asks only for her doll, left somewhere in the ruined town.', 'quest 5142 reward text; quest 5149 description'),
(13928, 2, 0, 255, 'Pamela was overjoyed to have her doll back. Then, lonely for her family, she sent her new friend to Auntie Marlene on the hill near Andorhal, who might know where her father is, and to Uncle Carlin, whom she can hear crying at night far to the east.', 'quest 5149 reward text; creature_text 10926 group 4 (Hurray! My doll!); quests 5152, 5241 descriptions'),
(13928, 3, 0, 255, 'Marlene was stricken to learn that Pamela, so young and happy a child, had perished. The girl does not understand what became of her father, Joseph, and even if she could, Marlene has not the heart to tell her.', 'quest 5152 reward text'),
(13928, 4, 0, 255, 'At Light''s Hope Chapel the news broke Carlin''s heart. He would switch places with his niece in an instant, he cried, and wander dead Darrowshire a ghost and alone rather than live on while she suffers. The news cannot change fate, but it makes his duty to revenge burn hotter than ever.', 'quest 5241 reward text'),
(13929, 1, 0, 255, 'The Annals tell an ugly tale. In the middle of the battle Captain Redpath was corrupted by Marduk the Black, and his taint turned the defenders against their own allies, so that Darrowshire was betrayed from within. Chromie calls it an ill fate, and one worth trying to change.', 'quest 5154 reward text; page_text 2371-2376 (Annals)'),
(13929, 2, 0, 255, 'Through Chromie''s magic the Annals have grown new pages at their end, carrying the history beyond the battle. One passage tells of another Redpath, Carlin, who survived Joseph''s betrayal and is now in the east at Light''s Hope Chapel.', 'quest 5210 description'),
(13929, 3, 0, 255, 'Carlin knew the book at once, for Darrowshire was his home, and in its new pages he found passages about himself and his brother Joseph. To learn the truth he sent for the relics of the battle: Davil Lightfire''s libram from the town hall of Hearthglen, Redpath''s cracked shield from Gahrron''s Withering, the skull of Horgus from Blackwood Lake and the shattered sword of Marduk from the gorge west of Corin''s Crossing.', 'quest 5210 reward text; quests 5168, 5181 descriptions (offered by Carlin at the 5210 turn-in); page_text 2377-2391 (Extended Annals)'),
(13930, 1, 0, 255, 'Carlin gathered the relics together and sent them on to Chromie in the ruined inn of Andorhal, where together they wove a spell to raise the spirits of Darrowshire. With the relic bundle set in the town square the battle would be fought again, and two things had to come to pass: Davil Lightfire must live until Horgus falls, and Captain Redpath must survive long enough to be corrupted, then be defeated, so that his spirit is saved.', 'quest 5941 description and reward text; quest 5721 description'),
(13930, 2, 0, 255, 'When it was done, Joseph''s spirit appeared in the square and went home at last. Pamela, overjoyed, said her daddy had chased the ghosts away and had told her to welcome the one who saved him, so she made tea, with lots of sugar. Her father also left a key to an old chest behind the house, with his thanks.', 'quest 5721 reward text; quest 5942 description (offered by Pamela at the 5721 turn-in); creature_text 10936 (Pamela? ... I''m finally home)'),
(13931, 1, 0, 255, 'The last task is his own. In life Nathanos was cut down on this very farm by a monstrous abomination and woke as Scourge, his mind bound to the Lich King''s until Sylvanas freed him. He hunted the beast across the wastes for months until it fled into Stratholme, and now he wants it destroyed: the abomination Ramstein.', 'quest 6163 description and request text'),
(13931, 2, 0, 255, 'Ramstein''s head was brought back to the stead. Nathanos, wondering aloud whether the beast had begged for mercy or could even know what mercy was, swore to hang it upon his wall. Then, for once, the Blightcaller saluted his recruit and granted a place among his champions.', 'quest 6163 reward text'),
(13932, 1, 0, 255, 'The Crimson Courier never reached Tyr''s Hand. His report was carried to the Marris Stead instead, and Nathanos, reading it, laughed aloud: at long last there was an opportunity to destroy the Scarlet Oracle.', 'quest 14350 reward text'),
(13932, 2, 0, 255, 'Nathanos rewrote the command. A soldier who bit into one of his rotten apples walked into Tyr''s Hand wearing a crusader''s face and handed it to Crusader Lord Valdelmar, who took the courier for a lost man returned. The Grand Crusader''s request was unusual, but it would be done: the Oracle would be sent to Stratholme. Back at the stead Nathanos gloated that his deception had gone unnoticed.', 'quest 6146 description and reward text; quest 6147 description and reward text'),
(13932, 3, 0, 255, 'The Oracle was Demetria, chief advisor to the Grand Crusader, credited with several of the Crusade''s victories against the Scourge and named for her otherworldly senses. Whatever she foresaw, it did not save her from the ambush on the road out of Tyr''s Hand. Nathanos judged that the Crusade would be reeling from the blow for years.', 'quest 6148 description and reward text'),
(13933, 1, 0, 255, 'The spirit of Alexandros Mograine came to his son. Then the Lich King appeared, admitted it, struck down the defenders and seized Tirion. Darion turned on his master and threw the Ashbringer to Tirion, in whose hands it was cleansed. Struck by the blade, the Lich King withdrew, swearing their next meeting would not be on holy ground. There Tirion called for a union of the Argent Dawn and the Silver Hand, and the Argent Crusade was born.', 'creature_text 29173 groups 77-85; creature_text 29175 groups 53-66; creature_text 29183 groups 47-58');
INSERT INTO `mod_lore_codex_trigger` (`Entry`, `Type`, `Value`, `Part`) VALUES
